-- Catalog sync: every product in data/products.js. Generated by scripts/build.js; don't edit. Applied by the deploy
-- (and scripts/dev.js locally) after the migrations. Re-applying it is harmless.
UPDATE products SET published = 0, deleted_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'), updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE source = 'catalog' AND deleted_at IS NULL;
-- Platform sync: creators, projects, Stacclets, Pacs and polls (data/creators.js, projects.js, stacclets.js, pacs.js, polls.js).
INSERT INTO creators (id, slug, name, source, trusted, published, catalog_hash, created_at, updated_at) VALUES ('autostacc', 'autostacc', 'AutoStacc', 'catalog', 1, 1, 'e5593688e5474ff7', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'))
  ON CONFLICT (id) DO UPDATE SET slug = excluded.slug, name = excluded.name, source = excluded.source, trusted = excluded.trusted, published = excluded.published, catalog_hash = excluded.catalog_hash, deleted_at = NULL, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now')
  WHERE creators.source = 'catalog' AND (creators.catalog_hash IS NOT excluded.catalog_hash OR creators.deleted_at IS NOT NULL);
UPDATE creators SET published = 0, deleted_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'), updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE source = 'catalog' AND deleted_at IS NULL AND id NOT IN ('autostacc');
